"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useMorphoMarkets } from "hooks/morpho";
import { useMemo } from "react";
import { ArrowUpRight } from "react-feather";
import { Link } from "react-router-dom";
import { Button, Flex, Text, styled, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useBorrowContext } from "../ContextProvider";
import { transformMorphoMarketToBorrowData } from "../utils";
const CardWrapper = styled(Flex, {
  flexDirection: "column",
  width: "100%",
  gap: "$spacing16"
});
const Card = styled(Flex, {
  flexDirection: "column",
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  p: "$spacing24",
  gap: "$spacing24"
});
const LabelText = styled(Text, {
  color: "$neutral2",
  variant: "body2",
  $sm: {
    variant: "body3"
  }
});
const ValueText = styled(LabelText, {
  color: "$neutral1"
});
const Divider = styled(Flex, {
  height: 1,
  width: "100%",
  backgroundColor: "$surface3"
});
const ActionButton = styled(Button, {
  borderRadius: "$roundedFull",
  py: "$spacing12"
});
const DataRow = ({
  label,
  value,
  subValue,
  icon
}) => <Flex row justifyContent="space-between" alignItems="center" width="100%">
    <LabelText color="$neutral2">{label}</LabelText>
    <Flex row alignItems="flex-end" gap={"$spacing8"}>
      <Flex flexDirection="row" alignItems="center" gap="$gap8">
        {icon}
        <ValueText color="$neutral1">{value}</ValueText>
      </Flex>
      {subValue && <Flex
  $sm={{ display: "none" }}
  backgroundColor="$surface3"
  paddingHorizontal="$spacing8"
  paddingVertical="$spacing2"
  borderRadius="$roundedFull"
>
          <Text variant="body4" color="$neutral2">
            {subValue}
          </Text>
        </Flex>}
    </Flex>
  </Flex>;
export default function BorrowCard() {
  const { formatFiatPrice, formatNumber } = useFormatter();
  const colors = useSporeColors();
  const { openTransaction } = useBorrowContext();
  const chainId = UniverseChainId.Mainnet;
  const { data: morphoMarkets } = useMorphoMarkets(chainId);
  const borrows = useMemo(() => {
    if (!morphoMarkets) return [];
    return morphoMarkets.map(transformMorphoMarketToBorrowData);
  }, [morphoMarkets]);
  if (!borrows.length) {
    return null;
  }
  return <CardWrapper>
      {borrows.map((borrow) => <Card key={borrow.id}>
          {
    /* Header */
  }
          <Flex row justifyContent="space-between" alignItems="center" width="100%">
            <Flex row alignItems="center" gap="$gap12">
              <Flex row alignItems="center">
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrow.collateral.symbol}
    tokenName={borrow.collateral.name}
    images={[getTokenLogoUrl(borrow.collateral.tokenId) || void 0]}
    size={32}
  />
                <Flex style={{ marginLeft: -12 }}>
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrow.loan.symbol}
    tokenName={borrow.loan.name}
    images={[getTokenLogoUrl(borrow.loan.tokenId) || void 0]}
    size={32}
  />
                </Flex>
              </Flex>
              <Link className="text-decoration-none" to={`/borrow/market?id=${borrow.marketId}`}>
                <Flex row alignItems="center" gap="$gap8">
                  <LabelText color="$neutral1">
                    {borrow.collateral.symbol}/{borrow.loan.symbol}
                  </LabelText>
                  <Flex backgroundColor="$surface3" px="$spacing8" py="$spacing2" borderRadius="$roundedFull">
                    <Text variant="body4" color="$neutral2">
                      {borrow.lltv.toFixed(1)}%
                    </Text>
                  </Flex>
                  <ArrowUpRight size={18} color={colors.neutral2.val} />
                </Flex>
              </Link>
            </Flex>
            <ValueText color={"$neutral1"}>{borrow.rate.toFixed(2)}%</ValueText>
          </Flex>

          <Divider />

          {
    /* Stats */
  }
          <Flex flexDirection="column" gap="$gap16">
            <DataRow
    label="Total Market Size"
    value={`${formatNumber({ input: borrow.marketSize.amount, type: NumberType.TokenTwoDecimals })} ${borrow.marketSize.symbol}`}
    subValue={formatFiatPrice({ price: borrow.marketSize.usdValue, type: NumberType.FiatTokenStats })}
  />
            <DataRow
    label="Total Liquidity"
    value={`${formatNumber({ input: borrow.liquidity.amount, type: NumberType.TokenTwoDecimals })} ${borrow.liquidity.symbol}`}
    subValue={formatFiatPrice({ price: borrow.liquidity.usdValue, type: NumberType.FiatTokenStats })}
  />
            <DataRow
    label="Trusted By"
    value=""
    icon={<Flex
      width={20}
      height={20}
      borderRadius="$roundedFull"
      backgroundColor="$surface3"
      justifyContent="center"
      alignItems="center"
    >
                  {
      /* Placeholder for "Trusted By" logo */
    }
                </Flex>}
  />
          </Flex>

          <Divider />

          <Flex flexDirection="row" gap="$spacing18" justifyContent="center">
            {
    /* Note: Borrow table doesn't have a specific position check here as Markets tab targets the market itself */
  }
            <ActionButton
    width="100%"
    onPress={() => {
      const mockPosition = {
        id: borrow.id,
        collateral: {
          amount: 0,
          value: 0,
          token: {
            id: borrow.collateral.tokenId,
            symbol: borrow.collateral.symbol,
            name: borrow.collateral.name
          }
        },
        loan: {
          amount: 0,
          value: 0,
          token: {
            id: borrow.loan.tokenId,
            symbol: borrow.loan.symbol,
            name: borrow.loan.name
          }
        },
        lltv: borrow.lltv,
        rate: borrow.rate,
        health: "0.00",
        utilization: 0
      };
      openTransaction(mockPosition, "borrow");
    }}
  >
              <Button.Text>Borrow</Button.Text>
            </ActionButton>
          </Flex>
        </Card>)}
    </CardWrapper>;
}
