"use strict";
import { motion } from "framer-motion";
import { Flex, Text, styled } from "ui/src";
import { useBorrowContext } from "../ContextProvider";
const ToggleButton = styled(Flex, {
  py: "$spacing8",
  px: "$spacing8",
  cursor: "pointer",
  position: "relative"
});
const ActiveUnderline = styled(motion.div, {
  position: "absolute",
  bottom: -1,
  left: 0,
  right: 0,
  height: 1,
  backgroundColor: "$neutral2"
});
export default function ToggleTab() {
  const { activeTab, setActiveTab } = useBorrowContext();
  const tabs = [
    { id: "Your positions", label: "Your positions" },
    { id: "Markets", label: "Markets" }
  ];
  return <Flex className="toggle-position-vault" row gap={"$spacing12"} borderBottomWidth={1} borderColor="transparent">
      {tabs.map((tab) => {
    const isActive = activeTab === tab.id;
    return <ToggleButton key={tab.id} onPress={() => setActiveTab(tab.id)}>
            <Text color={isActive ? "$neutral1" : "$neutral2"}>{tab.label}</Text>
            {isActive && <ActiveUnderline
      layoutId="activeTabUnderlineBorrow"
      transition={{
        type: "spring",
        stiffness: 500,
        damping: 30
      }}
    />}
          </ToggleButton>;
  })}
    </Flex>;
}
