"use strict";
export function transformMorphoMarketToBorrowData(market) {
  const marketSizeAmount = Number(market.totalSupplyAssetsFormatted);
  const liquidityAmount = Number(market.availableLiquidityFormatted);
  return {
    id: market.id,
    marketId: market.id,
    collateral: {
      symbol: market.collateralToken.symbol,
      name: market.collateralToken.name,
      tokenId: market.collateralToken.address
    },
    loan: {
      symbol: market.loanToken.symbol,
      name: market.loanToken.name,
      tokenId: market.loanToken.address
    },
    lltv: market.lltvPercent,
    marketSize: {
      amount: marketSizeAmount,
      symbol: market.loanToken.symbol,
      usdValue: market.totalSupplyUsd
    },
    liquidity: {
      amount: liquidityAmount,
      symbol: market.loanToken.symbol,
      usdValue: market.availableLiquidityUsd
    },
    rate: market.borrowRate
  };
}
export function transformMorphoBorrowPositionToPositionData(position, borrowRate, collateralPriceUsd, loanPriceUsd) {
  const collateralAmount = Number(position.collateralFormatted);
  const borrowAmount = Number(position.borrowAssetsFormatted);
  return {
    id: position.marketId,
    collateral: {
      amount: collateralAmount,
      value: collateralAmount * collateralPriceUsd,
      token: {
        id: position.collateralToken.address,
        symbol: position.collateralToken.symbol,
        name: position.collateralToken.name
      }
    },
    loan: {
      amount: borrowAmount,
      value: borrowAmount * loanPriceUsd,
      token: {
        id: position.loanToken.address,
        symbol: position.loanToken.symbol,
        name: position.loanToken.name
      }
    },
    rate: borrowRate,
    health: position.healthFactor === Infinity ? "> 10" : position.healthFactor.toFixed(2),
    utilization: position.ltv
  };
}
